import { useVirtualizer } from '@tanstack/react-virtual';
import clsx from 'clsx';
import React, { useRef } from 'react';

import { DataTableV2Body } from './DataTableV2Body.js';
import { DataTableV2Header } from './DataTableV2Header.js';
import { dataTableV2VirtualizationContainerCSS } from './DataTableV2VirtualizationContainer.sty.js';
import { _LoadingState } from '../features/LoadingState.js';
import { type Table } from '../hooks/useTable/types.js';

export function DataTableV2VirtualizationContainer<T>(props: {
  table: Table<T>;
}) {
  const { table } = props;

  const parentRef = useRef<HTMLDivElement | null>(null);

  const rows = table.getRowModel().rows;
  const visibleColumns = table.getVisibleLeafColumns();

  const rowVirtualizer = useVirtualizer({
    count: rows?.length ?? 0,
    getScrollElement: () => parentRef.current,
    overscan: 5,
    indexAttribute: 'data-row',
    // FIXME: Make this check a bit nicer
    paddingStart: table.getHeaderGroups().length === 1 ? 38 : 75,
    scrollMargin: table.getHeaderGroups().length === 1 ? 38 : 75,
    estimateSize() {
      return 37;
    },
  });

  const columnVirtualizer = useVirtualizer({
    count: visibleColumns.length,
    getScrollElement: () => parentRef.current,
    indexAttribute: 'data-column',
    estimateSize() {
      return 150;
    },
    overscan: 5,
    horizontal: true,
  });

  const headerCount =
    table.getHeaderGroups()[0].headers.length && table.getHeaderGroups().length;
  const headerHeight =
    headerCount === 0 ? 0 : rowVirtualizer.options.paddingStart;

  return (
    <div
      ref={parentRef}
      className={clsx(
        'strato-table-virtualization-container',
        dataTableV2VirtualizationContainerCSS({
          contained: table.getVisualVariantOptions().contained,
        }),
      )}
      style={{
        // if nested headers min height is 3 rows, otherwise min height is 2 rows
        minHeight: headerCount === 2 ? 112 : 75,
      }}
    >
      {visibleColumns.length > 0 && (
        <div
          role="grid"
          style={{
            display: 'grid',
            height: rowVirtualizer.getTotalSize(),
            // TODO: This will require some sizing smartness, that would be nice
            // to already come from the SizingFeature.
            gridTemplateColumns: table.getTableGridTemplate(),
            gridTemplateRows: `repeat(${
              headerCount + rows.length
            }, minmax(min-content, 37px))`,
          }}
        >
          <DataTableV2Header />
          <DataTableV2Body
            rows={rows}
            rowVirtualizer={rowVirtualizer}
            columnVirtualizer={columnVirtualizer}
          />
        </div>
      )}
      {table.getState().loading && (
        // eslint-disable-next-line react/jsx-pascal-case
        <_LoadingState headerHeight={headerHeight} />
      )}
    </div>
  );
}
